def is_k_colorable(n, edges, k):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    coloring = {}
    def solve(node):
        if node == n:
            return True
        for color in range(k):
            if all(coloring.get(neighbor) != color for neighbor in adj[node]):
                coloring[node] = color
                if solve(node + 1):
                    return True
                del coloring[node]
        return False
    return solve(0)

