def get_3_partite_edges(n1, n2, n3):
    edges = []
    # Partition 1: 0 to n1-1
    # Partition 2: n1 to n1+n2-1
    # Partition 3: n1+n2 to n1+n2+n3-1
    for i in range(n1):
        for j in range(n1, n1+n2):
            edges.append((i, j))
    for i in range(n1, n1+n2):
        for j in range(n1+n2, n1+n2+n3):
            edges.append((i, j))
    for i in range(n1+n2, n1+n2+n3):
        for j in range(n1):
            edges.append((i, j))
    return edges

