import random
def generate_random_3_partite(n1, n2, n3, num_edges):
    all_possible_edges = []
    for i in range(n1):
        for j in range(n1, n1+n2):
            all_possible_edges.append((i, j))
    for i in range(n1, n1+n2):
        for j in range(n1+n2, n1+n2+n3):
            all_possible_edges.append((i, j))
    for i in range(n1+n2, n1+n2+n3):
        for j in range(n1):
            all_possible_edges.append((i, j))

    # Randomly select num_edges
    edges = random.sample(all_possible_edges, num_edges)
    return edges

def check_constraints(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    degrees = [len(adj[i]) for i in range(n)]
    min_deg = min(degrees)
    max_deg = max(degrees)
    num_edges = len(edges)

    # Check if 3-colorable
    def is_k_colorable(k):
        coloring = {}
        def solve(node):
            if node == n:
                return True
            for color in range(k):
                if all(coloring.get(neighbor) != color for neighbor in adj[node]):
                    coloring[node] = color
                    if solve(node + 1):
                        return True
                    del coloring[node]
            return False
        return solve(0)

    # Check if 2-colorable
    is_2_colorable = is_k_colorable(2)
    is_3_colorable = is_k_colorable(3)

    return min_deg, max_deg, num_edges, is_2_colorable, is_3_colorable

